    ap_sync_reg_K0_U0_ap_ready_assign_proc : process(ap_clk)
    begin
        if (ap_clk'event and ap_clk =  '1') then
            if (ap_rst_n_inv = '1') then
                ap_sync_reg_K0_U0_ap_ready <= ap_const_logic_0;
            else
                if (((ap_sync_ready and ap_start) = ap_const_logic_1)) then 
                    ap_sync_reg_K0_U0_ap_ready <= ap_const_logic_0;
                else 
                    ap_sync_reg_K0_U0_ap_ready <= ap_sync_K0_U0_ap_ready;
                end if; 
            end if;
        end if;
    end process;


    ap_sync_reg_entry_proc_U0_ap_ready_assign_proc : process(ap_clk)
    begin
        if (ap_clk'event and ap_clk =  '1') then
            if (ap_rst_n_inv = '1') then
                ap_sync_reg_entry_proc_U0_ap_ready <= ap_const_logic_0;
            else
                if (((ap_sync_ready and ap_start) = ap_const_logic_1)) then 
                    ap_sync_reg_entry_proc_U0_ap_ready <= ap_const_logic_0;
                else 
                    ap_sync_reg_entry_proc_U0_ap_ready <= ap_sync_entry_proc_U0_ap_ready;
                end if; 
            end if;
        end if;
    end process;

    K0_U0_ap_continue <= ap_const_logic_1;
    K0_U0_ap_start <= ((ap_sync_reg_K0_U0_ap_ready xor ap_const_logic_1) and ap_start and ap_const_logic_1);
    K0_U0_start_full_n <= (start_for_K2_U0_full_n and start_for_K1_U0_full_n);
    K1_U0_ap_continue <= ap_const_logic_1;
    K1_U0_ap_start <= start_for_K1_U0_empty_n;
    K1_U0_s1_to_k3_fifo_cap <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(s1_to_k3_fifo_cap),10))),32));
    K1_U0_s1_to_k3_num_data_valid <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(s1_to_k3_num_data_valid),10))),32));
    K2_U0_ap_continue <= ap_const_logic_1;
