    K3_U0_s3_to_k4_num_data_valid <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(s3_to_k4_num_data_valid),3))),32));
    K4_U0_ap_continue <= ap_const_logic_1;
    K4_U0_ap_start <= start_for_K4_U0_empty_n;
    ap_done <= K4_U0_ap_done;
    ap_idle <= (entry_proc_U0_ap_idle and K4_U0_ap_idle and K3_U0_ap_idle and K2_U0_ap_idle and K1_U0_ap_idle and K0_U0_ap_idle);
    ap_ready <= ap_sync_ready;

    ap_rst_n_inv_assign_proc : process(ap_rst_n)
    begin
                ap_rst_n_inv <= not(ap_rst_n);
    end process;

    ap_sync_K0_U0_ap_ready <= (ap_sync_reg_K0_U0_ap_ready or K0_U0_ap_ready);
    ap_sync_entry_proc_U0_ap_ready <= (entry_proc_U0_ap_ready or ap_sync_reg_entry_proc_U0_ap_ready);
    ap_sync_ready <= (ap_sync_entry_proc_U0_ap_ready and ap_sync_K0_U0_ap_ready);
    entry_proc_U0_ap_continue <= ap_const_logic_1;
    entry_proc_U0_ap_start <= ((ap_sync_reg_entry_proc_U0_ap_ready xor ap_const_logic_1) and ap_start and ap_const_logic_1);
    in_r_0_RID <= ap_const_lv1_0;
